DROP TABLE IF EXISTS notams;
CREATE TABLE notams (
    id TEXT PRIMARY KEY,
    location TEXT NOT NULL,
    q_code TEXT,
    notam_code TEXT,
    message TEXT NOT NULL,
    valid_from DATETIME,
    valid_to DATETIME,
    risk_level TEXT,
    is_active BOOLEAN DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
